"use client"

import { useState, useEffect } from "react"

const contactInfo = [
  {
    title: "DIRECCIÓN",
    content: "Av. Tecnológica 123, Ciudad Futurista",
    icon: "📍",
    details: "Campus Principal - Edificio de Innovación"
  },
  {
    title: "TELÉFONO",
    content: "+57 (1) 234-5678",
    icon: "📞",
    details: "Línea directa de admisiones"
  },
  {
    title: "EMAIL",
    content: "info@institucionfuturista.edu.co",
    icon: "✉️",
    details: "Respuesta en menos de 24 horas"
  },
  {
    title: "HORARIOS",
    content: "Lunes a Viernes: 8:00 AM - 6:00 PM",
    icon: "🕒",
    details: "Sábados: 8:00 AM - 12:00 PM"
  }
]

const departments = [
  "Admisiones y Registro",
  "Información Académica",
  "Servicios Estudiantiles",
  "Biblioteca y Recursos",
  "Centro de Emprendimiento",
  "Bolsa de Empleo",
  "Bienestar Estudiantil",
  "Soporte Técnico"
]

export default function ContactoPage() {
  const [isVisible, setIsVisible] = useState(false)
  const [formData, setFormData] = useState({
    nombre: "",
    email: "",
    telefono: "",
    departamento: "",
    asunto: "",
    mensaje: ""
  })
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [submitStatus, setSubmitStatus] = useState<'idle' | 'success' | 'error'>('idle')

  useEffect(() => {
    setIsVisible(true)
  }, [])

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target
    setFormData(prev => ({
      ...prev,
      [name]: value
    }))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSubmitting(true)
    
    // Simulate form submission
    try {
      await new Promise(resolve => setTimeout(resolve, 2000))
      setSubmitStatus('success')
      setFormData({
        nombre: "",
        email: "",
        telefono: "",
        departamento: "",
        asunto: "",
        mensaje: ""
      })
    } catch (error) {
      setSubmitStatus('error')
    } finally {
      setIsSubmitting(false)
      setTimeout(() => setSubmitStatus('idle'), 5000)
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-white via-green-50 to-green-100">
      {/* Header Section */}
      <section className="pt-20 pb-16 px-4">
        <div className="container mx-auto max-w-6xl text-center">
          <div className={`transition-all duration-1000 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
            <h1 className="text-4xl md:text-6xl font-bold mb-6 bg-gradient-to-r from-green-600 via-green-700 to-green-800 bg-clip-text text-transparent" style={{ fontFamily: 'Orbitron, monospace' }}>
              CONTACTO
            </h1>
            <p className="text-xl md:text-2xl text-gray-600 max-w-4xl mx-auto leading-relaxed" style={{ fontFamily: 'Exo 2, sans-serif' }}>
              Estamos aquí para resolver tus dudas y acompañarte en tu camino hacia el futuro
            </p>
          </div>
        </div>
      </section>

      {/* Contact Info Cards */}
      <section className="pb-16 px-4">
        <div className="container mx-auto max-w-6xl">
          <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
            {contactInfo.map((info, index) => (
              <div 
                key={info.title}
                className={`bg-white rounded-2xl p-6 shadow-lg hover:shadow-xl transition-all duration-500 transform hover:-translate-y-2 border border-green-100 text-center ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}
                style={{ 
                  transitionDelay: `${index * 100}ms`,
                  fontFamily: 'Exo 2, sans-serif' 
                }}
              >
                <div className="w-16 h-16 bg-gradient-to-r from-green-500 to-green-600 rounded-2xl flex items-center justify-center mx-auto mb-4">
                  <span className="text-2xl">{info.icon}</span>
                </div>
                <h3 className="text-lg font-bold text-gray-800 mb-2">
                  {info.title}
                </h3>
                <p className="text-green-600 font-semibold mb-2">
                  {info.content}
                </p>
                <p className="text-sm text-gray-600">
                  {info.details}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Main Content */}
      <section className="pb-20 px-4">
        <div className="container mx-auto max-w-6xl">
          <div className="grid lg:grid-cols-2 gap-12">
            {/* Contact Form */}
            <div className="bg-white rounded-2xl p-8 shadow-lg border border-green-100">
              <h2 className="text-3xl font-bold text-gray-800 mb-6" style={{ fontFamily: 'Orbitron, monospace' }}>
                ENVÍANOS UN MENSAJE
              </h2>
              
              {submitStatus === 'success' && (
                <div className="mb-6 p-4 bg-green-100 border border-green-300 rounded-lg">
                  <p className="text-green-700 font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                    ¡Mensaje enviado exitosamente! Te contactaremos pronto.
                  </p>
                </div>
              )}

              {submitStatus === 'error' && (
                <div className="mb-6 p-4 bg-red-100 border border-red-300 rounded-lg">
                  <p className="text-red-700 font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                    Hubo un error al enviar el mensaje. Por favor, intenta nuevamente.
                  </p>
                </div>
              )}

              <form onSubmit={handleSubmit} className="space-y-6" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="nombre" className="block text-sm font-semibold text-gray-700 mb-2">
                      Nombre Completo *
                    </label>
                    <input
                      type="text"
                      id="nombre"
                      name="nombre"
                      value={formData.nombre}
                      onChange={handleInputChange}
                      required
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300"
                      placeholder="Tu nombre completo"
                    />
                  </div>
                  <div>
                    <label htmlFor="email" className="block text-sm font-semibold text-gray-700 mb-2">
                      Correo Electrónico *
                    </label>
                    <input
                      type="email"
                      id="email"
                      name="email"
                      value={formData.email}
                      onChange={handleInputChange}
                      required
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300"
                      placeholder="tu@email.com"
                    />
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label htmlFor="telefono" className="block text-sm font-semibold text-gray-700 mb-2">
                      Teléfono
                    </label>
                    <input
                      type="tel"
                      id="telefono"
                      name="telefono"
                      value={formData.telefono}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300"
                      placeholder="+57 300 123 4567"
                    />
                  </div>
                  <div>
                    <label htmlFor="departamento" className="block text-sm font-semibold text-gray-700 mb-2">
                      Departamento
                    </label>
                    <select
                      id="departamento"
                      name="departamento"
                      value={formData.departamento}
                      onChange={handleInputChange}
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300"
                    >
                      <option value="">Selecciona un departamento</option>
                      {departments.map((dept) => (
                        <option key={dept} value={dept}>
                          {dept}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div>
                  <label htmlFor="asunto" className="block text-sm font-semibold text-gray-700 mb-2">
                    Asunto *
                  </label>
                  <input
                    type="text"
                    id="asunto"
                    name="asunto"
                    value={formData.asunto}
                    onChange={handleInputChange}
                    required
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300"
                    placeholder="¿En qué podemos ayudarte?"
                  />
                </div>

                <div>
                  <label htmlFor="mensaje" className="block text-sm font-semibold text-gray-700 mb-2">
                    Mensaje *
                  </label>
                  <textarea
                    id="mensaje"
                    name="mensaje"
                    value={formData.mensaje}
                    onChange={handleInputChange}
                    required
                    rows={6}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-green-500 transition-colors duration-300 resize-vertical"
                    placeholder="Escribe tu mensaje aquí..."
                  />
                </div>

                <button
                  type="submit"
                  disabled={isSubmitting}
                  className={`w-full py-4 px-6 rounded-lg font-bold text-white transition-all duration-300 transform hover:scale-105 ${
                    isSubmitting
                      ? 'bg-gray-400 cursor-not-allowed'
                      : 'bg-gradient-to-r from-green-600 to-green-700 hover:from-green-700 hover:to-green-800 shadow-lg hover:shadow-xl'
                  }`}
                >
                  {isSubmitting ? (
                    <span className="flex items-center justify-center">
                      <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Enviando...
                    </span>
                  ) : (
                    'Enviar Mensaje'
                  )}
                </button>
              </form>
            </div>

            {/* Additional Info */}
            <div className="space-y-8">
              {/* FAQ Section */}
              <div className="bg-white rounded-2xl p-8 shadow-lg border border-green-100">
                <h3 className="text-2xl font-bold text-gray-800 mb-6" style={{ fontFamily: 'Orbitron, monospace' }}>
                  PREGUNTAS FRECUENTES
                </h3>
                <div className="space-y-4" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                  <div>
                    <h4 className="font-semibold text-gray-800 mb-2">¿Cuándo inician las inscripciones?</h4>
                    <p className="text-gray-600 text-sm">Las inscripciones están abiertas todo el año. Contamos con múltiples fechas de inicio para adaptarnos a tu disponibilidad.</p>
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-800 mb-2">¿Ofrecen becas o financiamiento?</h4>
                    <p className="text-gray-600 text-sm">Sí, tenemos diversos programas de becas por mérito académico, situación socioeconómica y convenios empresariales.</p>
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-800 mb-2">¿Los títulos tienen validez nacional?</h4>
                    <p className="text-gray-600 text-sm">Todos nuestros programas están registrados ante el Ministerio de Educación Nacional y tienen plena validez.</p>
                  </div>
                </div>
              </div>

              {/* Visit Us */}
              <div className="bg-gradient-to-br from-green-600 to-green-700 rounded-2xl p-8 text-white">
                <h3 className="text-2xl font-bold mb-4" style={{ fontFamily: 'Orbitron, monospace' }}>
                  VISÍTANOS
                </h3>
                <p className="text-green-100 mb-6" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                  Conoce nuestras instalaciones, laboratorios y servicios. Agenda una visita guiada personalizada.
                </p>
                <div className="space-y-3 text-sm" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                  <div className="flex items-center">
                    <span className="w-2 h-2 bg-green-300 rounded-full mr-3"></span>
                    <span>Tours guiados disponibles</span>
                  </div>
                  <div className="flex items-center">
                    <span className="w-2 h-2 bg-green-300 rounded-full mr-3"></span>
                    <span>Asesoría académica personalizada</span>
                  </div>
                  <div className="flex items-center">
                    <span className="w-2 h-2 bg-green-300 rounded-full mr-3"></span>
                    <span>Información sobre becas y financiamiento</span>
                  </div>
                </div>
              </div>

              {/* Social Media */}
              <div className="bg-white rounded-2xl p-8 shadow-lg border border-green-100">
                <h3 className="text-2xl font-bold text-gray-800 mb-6" style={{ fontFamily: 'Orbitron, monospace' }}>
                  SÍGUENOS
                </h3>
                <p className="text-gray-600 mb-6" style={{ fontFamily: 'Exo 2, sans-serif' }}>
                  Mantente al día con nuestras novedades, eventos y oportunidades académicas.
                </p>
                <div className="grid grid-cols-2 gap-4">
                  <a href="#" className="flex items-center justify-center p-3 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors duration-300">
                    <span className="mr-2">📘</span>
                    <span className="font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>Facebook</span>
                  </a>
                  <a href="#" className="flex items-center justify-center p-3 bg-pink-50 text-pink-600 rounded-lg hover:bg-pink-100 transition-colors duration-300">
                    <span className="mr-2">📷</span>
                    <span className="font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>Instagram</span>
                  </a>
                  <a href="#" className="flex items-center justify-center p-3 bg-blue-50 text-blue-500 rounded-lg hover:bg-blue-100 transition-colors duration-300">
                    <span className="mr-2">🐦</span>
                    <span className="font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>Twitter</span>
                  </a>
                  <a href="#" className="flex items-center justify-center p-3 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors duration-300">
                    <span className="mr-2">📺</span>
                    <span className="font-medium" style={{ fontFamily: 'Exo 2, sans-serif' }}>YouTube</span>
                  </a>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>
    </div>
  )
}
